<?php
if(!defined('ABSPATH'))exit;
class MMC_Marketing_Admin{
 public function __construct(){add_action('admin_menu',array($this,'menu'));add_action('admin_post_mmc_marketing_generate',array($this,'generate'));add_action('admin_post_mmc_marketing_save_item',array($this,'save_item'));add_action('admin_post_mmc_marketing_save_meta',array($this,'save_meta'));}
 public function menu(){add_submenu_page('mmc-dashboard','Afiş / Sosyal / Meta','Afiş / Sosyal / Meta','mmc_manage_marketing','mmc-marketing',array($this,'page'));}
 private function guard(){if(!current_user_can('mmc_manage_marketing'))wp_die('Bu alan için yetkiniz yok.');}
 public function page(){ $this->guard(); $programs=MMC_Program_Service::all_programs(); $pid=absint($_GET['program_id']??0); if(!$pid&&$programs)$pid=(int)$programs[0]->id; $program=$pid?MMC_Program_Service::get_program($pid):null; $items=$pid?MMC_Marketing_Service::latest_items($pid):array(); $meta=$pid?MMC_Marketing_Service::meta_plan($pid):null; $statuses=MMC_Marketing_Service::item_statuses(); ?>
 <div class="wrap mmc-wrap"><h1>Afiş / Sosyal Medya / Meta</h1><p class="mmc-lead">Program Dosyasından kreatif brief, sosyal medya metni ve reklam hazırlık planı üretir. Yayın ve canlı reklam başlatma yönetici onayı gerektirir.</p>
 <div class="mmc-panel"><form method="get" class="mmc-inline-form"><input type="hidden" name="page" value="mmc-marketing"><label>Program<select name="program_id" onchange="this.form.submit()"><option value="">Seçin</option><?php foreach($programs as $p):?><option value="<?php echo esc_attr($p->id);?>" <?php selected($pid,$p->id);?>><?php echo esc_html($p->program_code.' — '.$p->province_name.' / '.$p->district_name);?></option><?php endforeach;?></select></label><noscript><?php submit_button('Göster','secondary','',false);?></noscript></form></div>
 <?php if(!$program):?><div class="notice notice-info"><p>Program seçin.</p></div></div><?php return;endif;?>
 <?php if(isset($_GET['mmc_notice'])):?><div class="notice notice-<?php echo esc_attr($_GET['mmc_type']??'success');?> is-dismissible"><p><?php echo esc_html(wp_unslash($_GET['mmc_notice']));?></p></div><?php endif;?>
 <div class="mmc-panel mmc-hero-panel"><div><h2><?php echo esc_html($program->program_code);?></h2><p><?php echo esc_html($program->province_name.' / '.$program->district_name);?></p></div><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="mmc_marketing_generate"><input type="hidden" name="program_id" value="<?php echo esc_attr($pid);?>"><?php wp_nonce_field('mmc_marketing_generate_'.$pid); submit_button($items?'Paketi Güncelle':'Pazarlama Paketini Oluştur','primary','',false);?></form></div>
 <div class="mmc-grid-2"><div><?php foreach(MMC_Marketing_Service::item_types() as $type=>$label): $item=$items[$type]??null;?><div class="mmc-panel"><h2><?php echo esc_html($label);?> <?php if($item):?><span class="mmc-badge"><?php echo esc_html($statuses[$item->status]??$item->status);?></span><?php endif;?></h2><?php if(!$item):?><p>Henüz oluşturulmadı.</p><?php else:?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="mmc_marketing_save_item"><input type="hidden" name="item_id" value="<?php echo esc_attr($item->id);?>"><input type="hidden" name="program_id" value="<?php echo esc_attr($pid);?>"><?php wp_nonce_field('mmc_marketing_item_'.$item->id);?><label class="mmc-block-label">Başlık<input type="text" name="title" value="<?php echo esc_attr($item->title);?>"></label><label class="mmc-block-label">Metin<textarea name="body" rows="7"><?php echo esc_textarea($item->body);?></textarea></label><label class="mmc-block-label">Brief<textarea name="brief" rows="5"><?php echo esc_textarea($item->brief);?></textarea></label><div class="mmc-form-grid"><label>Durum<select name="status"><?php foreach($statuses as $k=>$v):?><option value="<?php echo esc_attr($k);?>" <?php selected($item->status,$k);?>><?php echo esc_html($v);?></option><?php endforeach;?></select></label><label>Planlanan yayın<input type="datetime-local" name="scheduled_at" value="<?php echo esc_attr($item->scheduled_at?str_replace(' ','T',substr($item->scheduled_at,0,16)):'');?>"></label><label class="mmc-span-2">Yayın URL<input type="url" name="external_url" value="<?php echo esc_attr($item->external_url);?>"></label></div><?php submit_button('Kaydet','secondary','',false);?></form><?php endif;?></div><?php endforeach;?></div>
 <div><div class="mmc-panel"><h2>Meta Reklam Planı</h2><?php if(!$meta):?><p>Pazarlama paketini oluşturduğunuzda reklam planı da hazırlanır.</p><?php else:?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="mmc_marketing_save_meta"><input type="hidden" name="program_id" value="<?php echo esc_attr($pid);?>"><?php wp_nonce_field('mmc_marketing_meta_'.$pid);?><label class="mmc-block-label">Kampanya adı<input type="text" name="campaign_name" value="<?php echo esc_attr($meta->campaign_name);?>"></label><label class="mmc-block-label">Hedef coğrafya<input type="text" name="geo_summary" value="<?php echo esc_attr($meta->geo_summary);?>"></label><label class="mmc-block-label">Kitle notu<textarea name="audience_notes" rows="4"><?php echo esc_textarea($meta->audience_notes);?></textarea></label><div class="mmc-form-grid"><label>Günlük bütçe<input type="number" step="0.01" min="0" name="daily_budget" value="<?php echo esc_attr($meta->daily_budget);?>"></label><label>Toplam bütçe<input type="number" step="0.01" min="0" name="total_budget" value="<?php echo esc_attr($meta->total_budget);?>"></label><label>Başlangıç<input type="datetime-local" name="start_at" value="<?php echo esc_attr($meta->start_at?str_replace(' ','T',substr($meta->start_at,0,16)):'');?>"></label><label>Bitiş<input type="datetime-local" name="end_at" value="<?php echo esc_attr($meta->end_at?str_replace(' ','T',substr($meta->end_at,0,16)):'');?>"></label><label>Durum<select name="status"><?php foreach(array('draft'=>'Taslak','review'=>'Onay Bekliyor','approved'=>'Onaylandı','active'=>'Aktif','paused'=>'Duraklatıldı','stop_required'=>'Durdurma/Güncelleme Gerekli','completed'=>'Tamamlandı') as $k=>$v):?><option value="<?php echo esc_attr($k);?>" <?php selected($meta->status,$k);?>><?php echo esc_html($v);?></option><?php endforeach;?></select></label><label>Harcama<input type="number" step="0.01" min="0" name="spend" value="<?php echo esc_attr($meta->spend);?>"></label><label>Satın alma<input type="number" min="0" name="purchases" value="<?php echo esc_attr($meta->purchases);?>"></label><label>Atfedilen ciro<input type="number" step="0.01" min="0" name="revenue" value="<?php echo esc_attr($meta->revenue);?>"></label></div><div class="mmc-cards" style="grid-template-columns:repeat(2,1fr)"><div class="mmc-card"><span>CPA</span><strong><?php echo esc_html(number_format_i18n((float)$meta->cpa,2));?> TL</strong></div><div class="mmc-card"><span>ROAS</span><strong><?php echo esc_html(number_format_i18n((float)$meta->roas,2));?></strong></div></div><details><summary>Harici Meta kimlikleri</summary><div class="mmc-form-grid"><label>Campaign ID<input type="text" name="external_campaign_id" value="<?php echo esc_attr($meta->external_campaign_id);?>"></label><label>Ad Set ID<input type="text" name="external_adset_id" value="<?php echo esc_attr($meta->external_adset_id);?>"></label><label>Ad ID<input type="text" name="external_ad_id" value="<?php echo esc_attr($meta->external_ad_id);?>"></label></div></details><p><code>utm_source=<?php echo esc_html($meta->utm_source);?>&amp;utm_medium=<?php echo esc_html($meta->utm_medium);?>&amp;utm_campaign=<?php echo esc_html($meta->utm_campaign);?></code></p><?php submit_button('Meta Planını Kaydet','secondary','',false);?></form><?php endif;?></div><div class="mmc-panel"><h2>Canlı Meta API</h2><p>Bu sürüm reklamı otomatik başlatmaz. Kampanya planını, UTM yapısını ve performans alanlarını hazırlar. Canlı kampanya oluşturma/başlatma sonraki güvenli entegrasyon aşamasında Meta erişim izinleri doğrulandıktan sonra yönetici onayıyla açılacaktır.</p></div></div></div></div><?php }
 public function generate(){ $this->guard();$pid=absint($_POST['program_id']??0);check_admin_referer('mmc_marketing_generate_'.$pid);$r=MMC_Marketing_Service::ensure_pack($pid,true);$this->redirect($pid,is_wp_error($r)?$r->get_error_message():'Pazarlama paketi oluşturuldu/güncellendi.',is_wp_error($r)?'error':'success'); }
 public function save_item(){ $this->guard();$id=absint($_POST['item_id']??0);$pid=absint($_POST['program_id']??0);check_admin_referer('mmc_marketing_item_'.$id);$r=MMC_Marketing_Service::save_item($id,$_POST);$this->redirect($pid,is_wp_error($r)?$r->get_error_message():'İçerik kaydedildi.',is_wp_error($r)?'error':'success'); }
 public function save_meta(){ $this->guard();$pid=absint($_POST['program_id']??0);check_admin_referer('mmc_marketing_meta_'.$pid);$r=MMC_Marketing_Service::save_meta_plan($pid,$_POST);$this->redirect($pid,is_wp_error($r)?$r->get_error_message():'Meta planı kaydedildi.',is_wp_error($r)?'error':'success'); }
 private function redirect($pid,$msg,$type){wp_safe_redirect(add_query_arg(array('page'=>'mmc-marketing','program_id'=>$pid,'mmc_notice'=>$msg,'mmc_type'=>$type),admin_url('admin.php')));exit;}
}
